// Generated by scripts/build-content.mjs from content/. Do not edit by hand.
'use strict';
(function (root) { const data = {"features":{"schema":1,"statuses":{"built":"Built in this release","partial":"Partly built","planned":"Not built yet","na":"Does not apply"},"items":[{"id":"job-experience-document-label","title":"Job document wording","status":"na","note":"This app has no job-related workflows.","group":"voice"},{"id":"language","title":"Language modes","status":"built","article":"languages","note":"English, Hong Kong Cantonese and bilingual modes, saved per computer, in the app and on the website.","group":"voice"},{"id":"funny-emoji","title":"Playfulness sliders and dialog emoji","status":"partial","article":"languages","note":"Separate English and Cantonese playfulness sliders (1 to 5) change the voice of status, empty-state, toast and error copy. The dialog emoji switch is built. Not every string has five voices yet.","group":"voice"},{"id":"personal-vocabulary","title":"Personal vocabulary upload","status":"built","note":"Upload or drop a versioned JSON file; it is validated in full (256 KiB, depth 8, 160 and 1,000 character limits) before anything applies, and it is never exported or added to settings history.","group":"voice","article":"vocabulary"},{"id":"vocabulary-drop-apply","title":"Drop a vocabulary file onto the app","status":"built","note":"Drop a vocabulary JSON file anywhere on the window to validate and apply it.","group":"voice","article":"vocabulary"},{"id":"school-mode","title":"School mode","status":"partial","note":"English only, plain wording, no emoji, vocabulary or dim sum, with those settings left out, and a PIN to turn it off. It is not yet shared across apps.","group":"voice","article":"school-mode"},{"id":"narration","title":"Spoken narrator","status":"partial","note":"Off by default; reads progress, results and notifications with separate English and Cantonese voice pickers, the voice in use shown, and speed and pitch. It does not yet detect a running screen reader.","group":"voice","article":"narrator"},{"id":"action-sound-effects","title":"Action sounds","status":"built","article":"motion-and-sound","note":"Short synthesized tones when hosting starts, goes live, stops or fails, with a Settings switch and volume. Visual feedback is complete without sound.","group":"voice"},{"id":"scheduled-settings","title":"Scheduled settings","status":"partial","note":"Time-of-day schedules for theme, motion, sounds and focus using local time, with precedence and history entries. Date ranges and outside sources are not built.","group":"voice","article":"schedules"},{"id":"display-name","title":"Rename the app","status":"built","article":"settings","note":"Change the name shown in the window title and header; one action restores the shipped name. Data folders and package ids never change.","group":"voice"},{"id":"adhd-modes","title":"Focus modes","status":"built","article":"focus-modes","note":"Focus, Low stimulation, Time awareness, One thing at a time and Momentum, each its own switch, all off by default.","group":"voice"},{"id":"dim-sum","title":"Dim sum surprise","status":"partial","article":"dim-sum","note":"A 1 in 10 chance at launch of a non-blocking dim sum note with English and Cantonese names. Pictures are not shown yet because the app makes no network requests from its interface.","group":"voice"},{"id":"dim-sum-photo-source","title":"Dim sum photo source","status":"planned","note":"Not built yet.","group":"voice"},{"id":"material-design","title":"Material Design 3","status":"built","article":"appearance","note":"Material 3 colour roles, shapes and one type scale, navigation rail and bottom bar, generated from one seed colour; on Windows the app draws its own title bar beside the system caption buttons.","group":"look"},{"id":"workflow-navigation","title":"Workflow navigation","status":"built","article":"getting-around","note":"Five destinations in a navigation rail, a bottom bar in narrow windows, and the current step always visible on Host.","group":"look"},{"id":"motion","title":"Motion with a reduced-motion path","status":"built","article":"motion-and-sound","note":"Full, gentle or off, following the system reduced-motion setting. No state is carried by motion alone.","group":"look"},{"id":"live-charts","title":"Live charts","status":"partial","note":"Sessions shows a 14-day chart of outcomes that redraws as sessions finish, with a screen-reader table. Not a streaming chart of a running session.","group":"look"},{"id":"appearance-editor","title":"Per-element appearance editor","status":"planned","note":"Not built yet. Global appearance settings exist.","group":"look"},{"id":"color-picker","title":"Colour picker","status":"partial","article":"appearance","note":"Seed colour by hue wheel, swatches or hex, with the full scheme regenerated live. Colour-space translation is not built.","group":"look"},{"id":"logo-customization","title":"Logo customization","status":"planned","note":"Not built yet.","group":"look"},{"id":"overlay-panels","title":"Overlays and panels","status":"built","article":"getting-around","note":"Notification centre, command palette and confirmations open as layered panels with focus return and Escape.","group":"look"},{"id":"collapse-filters","title":"Collapsible filters and statistics","status":"built","article":"sessions","note":"Session filters and statistics fold away and remember their state.","group":"look"},{"id":"accessibility-sizing","title":"Accessibility and sizing","status":"built","article":"accessibility","note":"Text size from 90 to 150 percent with the whole window always reachable, comfortable or compact density, visible focus everywhere, and every screen audited automatically (WCAG 2.2 AA, keyboard walk, clipping) at four window sizes, both themes and all language modes.","group":"look"},{"id":"functional-ui","title":"Truthful empty states","status":"built","article":"hosting","note":"No link, count or status is shown unless the backend reported it.","group":"look"},{"id":"onboarding-wizard","title":"First-run setup","status":"built","article":"getting-started","note":"Three steps: language and voice, a real Docker and tunnel check, then a short tour. Skippable, resumable, and reopenable from Settings.","group":"nav"},{"id":"tabs","title":"Tabbed navigation","status":"built","note":"A Workspace tab plus utility tabs opened from a searchable New tab catalogue, with Ctrl+T, Ctrl+W and Ctrl+Tab. Tabs persist.","group":"nav"},{"id":"regex-search","title":"Regex builder on every search","status":"partial","article":"search-and-regex","note":"Every search box has an adjacent regex builder with flags, live token explanation, match count, validation and a time limit. Full RegexBuddy parity is not built.","group":"nav"},{"id":"command-palette","title":"Command palette","status":"built","article":"command-palette","note":"Ctrl+Shift+F opens every destination, action and setting; picking one jumps to it and highlights it. Card or full-window size is remembered.","group":"nav"},{"id":"extension-support","title":"Extension support","status":"planned","note":"Not built yet. Planned: extensions tailored to sharing apps, each with a versioned manifest, an out-of-process protocol and declared permissions you allow before it runs, with a searchable manager, useful built-in extensions and an author guide.","group":"nav"},{"id":"context-menus","title":"Context menus","status":"partial","article":"getting-around","note":"Right-click or Shift+F10 opens a filterable menu; settings show live switches and choices beside their labels that work without closing the menu. Appearance and lock entries are not built.","group":"nav"},{"id":"menu-shortcuts","title":"Shortcuts shown in menus","status":"built","article":"command-palette","note":"Menus and the palette show each working shortcut.","group":"nav"},{"id":"rich-controls","title":"Rich controls","status":"partial","note":"Links and addresses carry copy and open controls, and settings in menus and the command palette show live switches. Not every value does yet.","group":"nav","article":"command-palette"},{"id":"guided-forms","title":"Guided forms","status":"partial","article":"hosting","note":"The project form explains each field and validates the port as you type.","group":"nav"},{"id":"info-icon-guidance","title":"Info buttons on controls","status":"partial","article":"settings","note":"Every setting has an info button with an explanation. Worked examples and playgrounds are not built.","group":"nav"},{"id":"settings-explanations","title":"Settings that explain themselves","status":"built","article":"settings","note":"Each setting states what it changes and where.","group":"nav"},{"id":"blank-editors","title":"Presets for blank editors","status":"na","note":"The app has no free-form editors.","group":"nav"},{"id":"super-confirmation","title":"Two-key confirmation","status":"built","article":"safety","note":"Stopping a live link, clearing history and resetting settings need two separate keys and a slider, with an emergency exit and Escape.","group":"safety"},{"id":"element-locks","title":"Element locks","status":"planned","note":"Not built yet.","group":"safety"},{"id":"support-tickets","title":"Support ticket recovery","status":"planned","note":"Not built yet.","group":"safety"},{"id":"unlock-ladder","title":"Unlock ladder","status":"planned","note":"Not built yet.","group":"safety"},{"id":"authenticator","title":"Built-in authenticator","status":"built","note":"TOTP codes with SHA-1, SHA-256 and SHA-512, secrets sealed in the system vault, search, guarded export. Codes match the RFC 6238 vectors in tests.","group":"safety"},{"id":"qr-pairing","title":"QR pairing","status":"planned","note":"Not built yet.","group":"safety"},{"id":"honest-monetization","title":"Free, no nagging","status":"built","article":"about","note":"The app is free, has no paid tier, ads or upgrade prompts.","group":"safety"},{"id":"local-history","title":"Local version history","status":"partial","article":"sessions","note":"Every hosting attempt and every settings change is kept locally; a settings revision can be restored as a new revision. Encrypted snapshots are not built.","group":"records"},{"id":"exports","title":"Export everything","status":"partial","article":"sessions","note":"Sessions as JSON, CSV or Markdown; settings, settings history and notifications as JSON. Archives are not built.","group":"records"},{"id":"bulk-actions","title":"Bulk actions","status":"partial","article":"sessions","note":"Select many sessions or notifications to export or remove them.","group":"records"},{"id":"changelog","title":"Changelog viewer","status":"partial","article":"about","note":"Every release with date, changes and commit, with date-range filter and regex search. Exporting the filtered view is not built.","group":"records"},{"id":"offline-docs","title":"Offline guide","status":"built","article":"getting-around","note":"Every article on the website ships inside the app and opens without a network.","group":"records"},{"id":"rendered-provider-text","title":"Rendered provider text","status":"na","note":"The app shows no provider-authored rich text.","group":"records"},{"id":"notifications","title":"Notifications and their centre","status":"built","article":"notifications","note":"Non-blocking toasts, a searchable notification centre with bulk clear, and errors that stay until dismissed.","group":"records"},{"id":"file-converter","title":"File converter","status":"partial","note":"Converts JSON lists, CSV and TSV to CSV, TSV, Markdown or JSON and states any loss before you save. Other formats are not built.","group":"tools","article":"tools"},{"id":"base64-tools","title":"Base64 tools","status":"partial","note":"Text and file encoding, standard, URL-safe and MIME alphabets, padding, three text encodings, strict decoding with exact positions, data: URLs, SHA-256 round-trip checks and session history. Streaming, pause and ZIP export are not built.","group":"tools","article":"tools"},{"id":"minecraft-server-manager","title":"Minecraft server manager","status":"planned","note":"Not built yet.","group":"tools"},{"id":"minecraft-world-generator","title":"Minecraft world generator","status":"planned","note":"Not built yet.","group":"tools"},{"id":"ollama-suite","title":"Ollama manager","status":"planned","note":"Not built yet.","group":"tools"},{"id":"external-editor","title":"Open in an external editor","status":"partial","note":"Detects VS Code (per-user, machine, Insiders, PATH) without running it and opens the project folder; also opens the file in the default editor or shows it in the file manager. Choosing another editor is not built.","group":"tools","article":"editor"},{"id":"download-handoff","title":"Browser download hand-off","status":"na","note":"There is no browser extension.","group":"tools"},{"id":"forge-publishing","title":"Publishing to a forge","status":"planned","note":"Not built yet.","group":"tools"},{"id":"progress-recovery","title":"Progress and recovery in place","status":"built","article":"hosting","note":"Progress shows on the step that is running and recovery actions appear on the step that failed.","group":"tools"},{"id":"drawesome-drawing","title":"Drawing and annotation","status":"planned","note":"Not built yet.","group":"tools"},{"id":"completeness-parity","title":"Feature inventory","status":"built","article":"features","note":"This list, with the same honest status in the app and on the website.","group":"evidence"},{"id":"front-provenance","title":"Version and build time on the first screen","status":"built","article":"about","note":"Shows the running version and its build time with seconds and time zone, read from the packaged build record, or says it is unavailable.","group":"evidence"},{"id":"product-evidence","title":"Real screenshots","status":"partial","note":"Website and README screenshots are rendered from the real interface by scripts/screens/shoot.sh with a scripted backend; they are not captures of live hosting.","group":"evidence"},{"id":"screen-recording","title":"Screen recording","status":"planned","note":"Not built yet.","group":"evidence"},{"id":"design-reference-parity","title":"Design reference parity","status":"partial","note":"The interface follows the checked-in design in design/canvas; a pixel comparison is not automated.","group":"evidence"},{"id":"design-folder","title":"Design files in the repository","status":"built","note":"All design artboards and notes live in design/.","group":"evidence"},{"id":"clipping-matrix","title":"Clipping checks","status":"partial","note":"npm run clip opens all six screens at 360, 768 and 1280 pixels in English, Cantonese and both, and reports cut-off or off-screen text. It needs Playwright with Chromium and is not run in CI yet.","group":"evidence"},{"id":"public-screenshot-gallery","title":"Public screenshot gallery","status":"partial","note":"The website has a gallery of interface renders. They are rendered with a scripted backend, not captured from live hosting.","group":"evidence"},{"id":"landing-site","title":"Material website","status":"partial","article":"features","note":"The website carries the feature list, articles, language modes, themes, motion settings, search with regex and the command palette. Not every app feature has a website equivalent.","group":"site"},{"id":"mobile-site","title":"Phone-friendly website","status":"built","note":"Every website section works from 320 px wide.","group":"site"},{"id":"installer-download-button","title":"Download button","status":"built","note":"Points at the latest published release and shows its version and date when the release exists.","group":"site"},{"id":"feature-articles","title":"An article per feature","status":"partial","article":"features","note":"Every built or partly built feature links to an article. Planned features do not have articles yet.","group":"site"},{"id":"vendored-fonts","title":"Bundled fonts","status":"built","note":"Roboto Flex, Roboto Mono and Material Symbols are copied from npm by scripts/vendor-assets.mjs into the app and the website.","group":"site"},{"id":"shared-link-embed","title":"Link preview image","status":"built","note":"The website has Open Graph tags and a preview image.","group":"site"},{"id":"homepage-link","title":"Website linked from the repository","status":"built","note":"The repository About field links to the website, and the README links to it at the top.","group":"site"},{"id":"vocabulary-unlock-boundary","title":"Private wording boundary","status":"na","note":"The app and website are public and have no signed-in surfaces.","group":"site"},{"id":"private-website-app","title":"Packaged website for private repositories","status":"na","note":"This repository is public.","group":"site"},{"id":"status-hub","title":"Status hub","status":"planned","note":"Not built yet.","group":"status"},{"id":"discord-status-bridge","title":"Discord status bridge","status":"na","note":"Part of the status hub app, not this one.","group":"status"},{"id":"panic-webhooks","title":"Panic webhooks","status":"na","note":"Part of the status hub app, not this one.","group":"status"},{"id":"tidbyt-displays","title":"Tidbyt displays","status":"na","note":"Part of the status hub app, not this one.","group":"status"},{"id":"build-entrypoints","title":"build.bat and build-installer.bat","status":"built","note":"Both exist at the repository root.","group":"build"},{"id":"fresh-build-run-command","title":"One build-and-run command","status":"partial","note":"build.bat builds; it does not launch the result yet.","group":"build"},{"id":"dependency-fetcher","title":"One-click dependency fetcher","status":"partial","note":"The tunnel helper downloads and is hash-verified automatically. Docker must still be installed by you.","group":"build"},{"id":"bundled-dependencies","title":"Bundled dependencies","status":"partial","note":"Fonts and icons are bundled; Docker is not.","group":"build"},{"id":"squirrel-installer","title":"Windows installer","status":"built","note":"Squirrel.Windows Setup.exe, RELEASES and full package are published with every release from main, first in v0.2.6. Unsigned.","group":"build"},{"id":"self-signing","title":"Code signing","status":"planned","note":"Builds are unsigned.","group":"build"},{"id":"auto-updates","title":"Automatic updates","status":"partial","note":"Installed copies check the release feed every four hours and offer an unsigned restart banner. Not yet proven on an installed copy updating to a newer release.","group":"build"},{"id":"app-icon","title":"Original icon","status":"built","note":"An original icon generated by scripts/build-icon.py from build/icon.svg into PNG and a multi-size .ico used by the window and the packaged executable.","group":"build"},{"id":"release-workflow","title":"A release on every main build","status":"built","note":"Every push to main builds the Windows portable executable and publishes the next tagged release with it.","group":"release"},{"id":"release-timing","title":"Workflow timing in release notes","status":"built","note":"Release notes state how long the build took.","group":"release"},{"id":"release-line-counts","title":"Line counts in release notes","status":"built","note":"Release notes list hand-written line counts from scripts/count-lines.mjs, run by the workflow.","group":"release"},{"id":"release-dim-sum-photo","title":"Dim sum photos in releases","status":"planned","note":"Not built yet.","group":"release"},{"id":"dim-sum-code-names","title":"Dim sum code names","status":"built","note":"Each release takes the next unused dish with a published photo from the public catalogue, recorded in its notes and shown in About.","group":"release"},{"id":"ci-bootstrap","title":"CI dependency bootstrap","status":"built","note":"Workflows install pinned Node and dependencies with npm ci.","group":"release"},{"id":"runner-selection","title":"Runner selection","status":"partial","note":"Uses GitHub-hosted Windows and Ubuntu runners.","group":"release"},{"id":"encrypted-public-builder","title":"Encrypted builder","status":"na","note":"For private repositories only.","group":"release"},{"id":"tabbed-readme","title":"Tabbed README","status":"partial","note":"The README uses collapsible sections.","group":"repo"},{"id":"human-time-estimate","title":"Human time estimate","status":"built","note":"The README shows an estimate range with its method, the counted lines from scripts/count-lines.mjs, the assumed rate and the arithmetic.","group":"repo"},{"id":"sanitized-instruction-copy","title":"Sanitized instruction copy","status":"partial","note":"AGENTS.md carries the public-safe rules.","group":"repo"},{"id":"agents-md-vocabulary-block","title":"Wording rules in AGENTS.md","status":"built","note":"AGENTS.md states the public wording boundary.","group":"repo"},{"id":"vocabulary-hash-lock","title":"Wording hash lock","status":"planned","note":"Not built yet.","group":"repo"},{"id":"roadmap-checklist","title":"ROADMAP.md checklist","status":"built","note":"ROADMAP.md is generated from this inventory.","group":"repo"},{"id":"feature-docs","title":"A Markdown file per feature","status":"partial","note":"content/articles holds one article per built area, shared by the app and website.","group":"repo"},{"id":"postman-collections","title":"API collections","status":"na","note":"The app exposes no HTTP API.","group":"repo"},{"id":"wiki-website-sync","title":"Wiki and website in sync","status":"partial","note":"The website and the in-app guide are generated from the same articles. There is no wiki.","group":"repo"},{"id":"handoff-record","title":"Handoff record","status":"built","note":"HANDOFF.md is kept current.","group":"repo"},{"id":"closeout-prompt","title":"Closeout prompt","status":"built","note":"CLOSEOUT_PROMPT.md holds a copy-ready prompt for the next session.","group":"repo"},{"id":"discussion-records","title":"Discussions as the record","status":"planned","note":"Not built yet.","group":"repo"},{"id":"project-board","title":"Linked project board","status":"planned","note":"Not built yet.","group":"repo"},{"id":"operational-skill","title":"Operational skill file","status":"partial","note":".claude/skills/tunnel-app-deployer-operations/SKILL.md records build, generation, screenshot, release and recovery routes. It has not been put through a skill evaluation.","group":"repo"},{"id":"readme-prompt-banner","title":"README prompt banner","status":"na","note":"Applies only to the instruction repository.","group":"repo"},{"id":"instruction-single-file-editions","title":"Single-file instruction editions","status":"na","note":"Applies only to the instruction repository.","group":"repo"},{"id":"project-profile","title":"Project memory folders","status":"na","note":"Applies only to the instruction repository.","group":"repo"},{"id":"roblox-model-catalogue","title":"Shared Roblox models","status":"na","note":"Applies only to games.","group":"tools"},{"id":"roblox-visual-realism","title":"Roblox visual realism","status":"na","note":"Applies only to games.","group":"tools"}],"groups":[["voice","Language, voice and personalization"],["look","Appearance and layout"],["nav","Navigation, search and commands"],["safety","Safety, locks and sign-in"],["records","Records, history and messages"],["tools","Built-in tools and hand-off"],["evidence","Completeness and evidence"],["site","Website and shared links"],["status","Status reporting"],["build","Build and install"],["release","Release pipeline"],["repo","Repository records"]]},"articles":[{"id":"about","title":"Version, changelog and price","summary":"The top bar shows the running version and the time it was built, with seconds and the time zone. Both come from the build record packaged with the app. A copy run from source has no build record and says Build time unavailable instead of guessing.","related":["settings","features"],"body":"## Version and build time\n\nThe top bar shows the running version and the time it was built, with seconds and the time zone. Both come from the build record packaged with the app. A copy run from source has no build record and says **Build time unavailable** instead of guessing.\n\n## Changelog\n\n**Settings › About › Changelog** lists every release with its date, changes and commit. Filter by a date range or search with the regex builder.\n\n## Price\n\nThe app is free. There is no paid tier, no advertising and no upgrade prompt."},{"id":"accessibility","title":"Accessibility","summary":"Keyboard first, readable at any size, and announced to screen readers.","related":["focus-modes","motion-and-sound","getting-around"],"body":"Keyboard first, readable at any size, and announced to screen readers.\n\n## Keyboard\n\nEvery control can be reached with **Tab**, has a visible focus ring, and works with **Enter** or **Space**. The command palette (**Ctrl+Shift+F**) reaches every screen, action and setting. **Shift+F10** opens the context menu of the focused item.\n\n- In menus and the palette, type to filter, use the **arrow keys** to move and **Enter** to run. Left and right change a choice in place.\n- In the tab bar, the **arrow keys**, **Home** and **End** move between tabs and **Delete** closes one.\n- Dialogs keep the keyboard inside until they close, then return you to where you were.\n\n## Size and density\n\n- **Text size** scales the whole interface from 90 to 150 percent.\n- **Density** switches between comfortable and compact spacing.\n- Layouts work from 390 pixels wide up, including a 1080p screen at 200 percent scale. Nothing is cut off, settings stack their controls under the label on narrow windows, and long addresses wrap only after dots, dashes and slashes.\n- At every text size the whole window stays reachable.\n\n## Screen readers\n\nProgress messages, copied links and notifications are announced through a polite live region. Icon glyphs are hidden, so buttons are read by their words, and icon-only buttons have names. The bell says how many notifications are unread. Menus are read as lists with the highlighted item, and the Sessions chart has the same numbers as a table. Errors use an alert role.\n\n## Contrast and motion\n\nColours are generated to keep text at a contrast ratio of at least 4.5 to 1 in both themes, including Cantonese text inside buttons. Motion follows your system's reduced-motion setting, and moving lines become solid lines.\n\n## How it is checked\n\nEvery screen and dialog is checked automatically before release: an accessibility audit against WCAG 2.2 AA, a keyboard walk, and a search for cut-off or overlapping text, in both themes, all three language modes and four window sizes (`npm run audit:ui`). Automated checks catch a lot, not everything; please report anything that gets in your way."},{"id":"appearance","title":"Appearance","summary":"Material Design 3 colours, shapes and type, all generated from one accent colour.","related":["accessibility","motion-and-sound","settings"],"body":"Material Design 3 colours, shapes and type, all generated from one accent colour.\n\n## Theme\n\n**Follow system**, **Light** or **Dark**. The button in the top bar flips between light and dark.\n\n## Accent colour\n\nDrag the hue slider, press a swatch, or type a hex value such as `#3ddbb4`. The app builds its whole colour scheme from it: primary, containers, surfaces and outlines in both light and dark. Text colours are chosen to keep a contrast ratio of at least 4.5 to 1.\n\n## Navigation rail\n\n**Expanded** writes each destination's name beside its icon and turns the New host button into a labelled button. **Compact** shows icons with small labels underneath. Switch with the menu button at the top of the rail or in this group. Windows narrower than 1100 pixels always use compact.\n\n## Window\n\nOn Windows the app draws its own title bar, with the app name, version, dim sum code name and build time. The minimise, maximise and close buttons are Windows' own, so Snap layouts work as usual. Drag the title bar to move the window. Other systems keep their normal window frame.\n\n## Type and icons\n\nText uses Roboto Flex, addresses and timings use Roboto Mono, and icons come from Material Symbols Rounded. All three are bundled, so the app never loads fonts from the internet.\n\n## What is not built yet\n\nEditing the look of a single element and translating colours between colour spaces are planned."},{"id":"authenticator","title":"Authenticator","summary":"Two-step sign-in codes, made on this computer.","related":["tools","safety","search-and-regex"],"body":"Two-step sign-in codes, made on this computer.\n\nOpen **Tools › Authenticator**, or search the palette (**Ctrl+Shift+F**) for *Authenticator*.\n\n## Add an account\n\nChoose **Add account**. Then do one of these:\n\n- Paste the whole `otpauth://totp/...` link that a website shows under its QR code.\n- Paste only the secret key, then fill in the name, the issuer and the code settings. Most sites use SHA-1, 6 digits and 30 seconds.\n\nSpaces and dashes in a secret are ignored. A secret that is not valid Base32 is rejected, and the message names the problem.\n\n## Using codes\n\nEach account shows its current code, a ring that empties as the code expires, and the next code. Select the code or **Copy** to copy it without spaces. The ring turns red in the last five seconds.\n\nSearch the list by name or issuer. The regex builder works here as it does everywhere else.\n\n## Where secrets are kept\n\nSecrets are encrypted with your operating system's protected storage before they are saved: Windows DPAPI, the macOS Keychain or the Linux secret service. Only the name, issuer and code settings are saved in plain form. When that storage is unavailable, adding accounts is turned off and the screen says why.\n\n## Export\n\n- **Export list** saves names, issuers and code settings. It never includes secrets, and the file says so.\n- **Export with secrets** saves full `otpauth://` links. It asks for a two-step confirmation first, because anyone with that file can make your codes. Keep it somewhere safe and delete it when you are done.\n\nRemoving an account also asks for confirmation. A removed secret cannot be recovered from this app."},{"id":"command-palette","title":"Command palette","summary":"Press Ctrl+Shift+F anywhere to find any screen, action, setting or article.","related":["search-and-regex","getting-around"],"body":"Press **Ctrl+Shift+F** anywhere to find any screen, action, setting or article.\n\n## Using it\n\n1. Press **Ctrl+Shift+F**, or the search bar at the top.\n2. Type. Results are grouped as screens, actions, settings and articles.\n3. Use the arrow keys and **Enter**, or click.\n\nChoosing a setting opens its group, scrolls to it, focuses it and highlights it for a moment. Choosing an action runs it, the same way its button would. Settings that are switches show a live switch in their row: click it, or press **Alt+Space**, to change the setting without leaving the palette.\n\n## Shortcuts\n\n| Shortcut | What it does |\n| --- | --- |\n| Ctrl+Shift+F | Open the command palette |\n| Ctrl+1 to Ctrl+6 | Host, Sessions, Tools, Features, Guide, Settings |\n| Ctrl+Shift+E | Open the chosen project folder in VS Code |\n| Ctrl+Enter | Host app (when a project is chosen) |\n| Ctrl+Shift+C | Copy the live link |\n| Ctrl+. | Stop sharing (opens the confirmation) |\n| Shift+F10 | Context menu for the focused item |\n| Escape | Close the palette, a menu or a dialog |\n\n## Size\n\n**Settings › Accessibility › Command palette size** switches between a centred card and the full window. The choice is remembered.\n\nThe palette has its own regex builder: press **.\\*** inside it."},{"id":"dim-sum","title":"Dim sum surprise","summary":"Each time the app opens there is a 1 in 10 chance of a small dim sum note.","related":["languages","settings"],"body":"Each time the app opens there is a 1 in 10 chance of a small dim sum note.\n\nThe note shows one dish with its English and Cantonese names, waits quietly in the corner, and fades on its own. It never appears during the first-run tour, while hosting is running, or after an error, and it never takes focus.\n\nThe switch in **Settings › Appearance** is a joke: turn it off and it turns itself back on.\n\nPictures of the dishes are planned; the app does not load images from the internet today."},{"id":"editor","title":"Opening a project in an editor","summary":"Once a project is chosen, the Host screen shows three buttons, also in the project's context menu:","related":["hosting","getting-around"],"body":"Once a project is chosen, the Host screen shows three buttons, also in the project's context menu:\n\n- **Open folder in VS Code** opens the project folder in Visual Studio Code. Shortcut: **Ctrl+Shift+E**.\n- **Open file in default editor** opens the Dockerfile or Compose file in the app your system uses for it.\n- **Show in file manager** opens the folder with the file selected.\n\nThe app looks for Visual Studio Code in the usual per-user and machine-wide locations, the Insiders edition and folders on your PATH, without running anything. If it is not found, that button is disabled and **Get VS Code** links to the official download page.\n\nOnly the project you chose can be opened this way.\n\n## Not built yet\n\nChoosing a different editor and opening exported files in VS Code are planned."},{"id":"features","title":"The feature inventory","summary":"The Features screen and the website list every feature this project aims to carry, with an honest status.","related":["about","getting-around"],"body":"The **Features** screen and the website list every feature this project aims to carry, with an honest status.\n\n| Status | Meaning |\n| --- | --- |\n| Built | Works in this release. |\n| Partly built | Some of it works; the note says what is missing. |\n| Not built yet | Planned, not available. |\n| Does not apply | Not relevant to this app; the note says why. |\n\nThe list in the app and on the website come from the same file, `content/features.json`, so they always agree. Built and partly built items link to their article. Search the list, filter by status, and press a card to open its article."},{"id":"focus-modes","title":"Focus modes","summary":"Five separate switches that make the app easier to follow. All are off until you turn them on.","related":["accessibility","motion-and-sound","settings"],"body":"Five separate switches that make the app easier to follow. All are off until you turn them on.\n\n| Mode | What it changes |\n| --- | --- |\n| Focus | Hides secondary notes, the requirements bar and the footer. |\n| Low stimulation | Softer colours and no motion. Your system's reduced-motion setting still applies on top. |\n| Time awareness | A clock in the top bar, and how long the current step has been running. |\n| One thing at a time | Host shows only the card for the step you are on. |\n| Momentum | A single line under the top bar names the next action. |\n\nThe modes are plain tools. They keep no streaks or scores and make no medical claims."},{"id":"getting-around","title":"Getting around","summary":"Six destinations, one search bar, and a menu on everything you can right-click.","related":["command-palette","notifications","tools"],"body":"Six destinations, one search bar, and a menu on everything you can right-click.\n\n## Destinations\n\n- **Host**: choose a project and share it.\n- **Sessions**: every hosting attempt on this computer.\n- **Tools**: a Base64 toolkit and a table converter.\n- **Features**: what the app does, with an honest status for each part.\n- **Guide**: these articles, bundled inside the app so they open offline.\n- **Settings**: appearance, motion, language, focus modes and data.\n\nIn a wide window they sit in the navigation rail on the left, each name written beside its icon. The menu button at the top of the rail collapses it to icons with small labels underneath, and expands it again; the choice is kept in **Settings › Appearance › Navigation rail**. Windows narrower than 1100 pixels use the compact rail, and below 860 pixels the destinations move to a bar at the bottom.\n\n## Context menus\n\nRight-click a link, a path, a session or selected text, or press **Shift+F10** on the focused item. Each menu starts with a filter field: type to narrow it. Menus show the shortcut for each item.\n\nSettings appear in menus with their live control beside the label: a switch for an on or off setting, and choice buttons for a setting with options. Right-click any setting row to get its own control at the top. Change them in place, and the menu stays open: **Space** or **Enter** flips a switch, and **Left** and **Right** move between choices. Every menu also ends with **Quick settings** for theme, motion, action sounds, focus and the narrator.\n\n## Panels\n\nThe notification centre, command palette and confirmations open over the screen. **Escape** closes the top one and focus returns to where you were.\n\n## The offline guide\n\nEvery article on the website ships inside the app. Links between articles stay inside the app, and the guide has its own search with the regex builder."},{"id":"getting-started","title":"Getting started","summary":"Install Docker, open the app, pick a project and press Host. The first-run tour checks your computer for you.","related":["hosting","getting-around","languages"],"body":"Install Docker, open the app, pick a project and press Host. The first-run tour checks your computer for you.\n\n## What you need\n\n- **Docker Desktop or Docker Engine**, running. The app checks for it on every launch and from **Check again** on the Host screen.\n- **Docker Compose v2** if you host a Compose project. It ships with Docker Desktop.\n- **The tunnel helper** (`cloudflared`). If it is not installed, the app downloads a pinned official release the first time you host and checks its SHA-256 hash before using it. Nothing is installed system-wide.\n\n## The first-run tour\n\nThe tour has three steps:\n\n1. **Language and voice.** Choose English, Cantonese or bilingual, and how playful the wording should be.\n2. **A real check.** The app asks Docker and the tunnel helper whether they are ready and shows the answers.\n3. **Done.** You land on the Host screen.\n\nYou can skip the tour at any step and run it again from **Settings › About › Run the welcome tour again**.\n\n## Your first link\n\n1. On **Host**, choose **Dockerfile** or **Compose**.\n2. Press the large picker and choose the file.\n3. For Compose, pick the web service. Leave the port empty unless the app cannot detect it.\n4. Press **Host app** and watch each step finish.\n5. When the link card appears, press **Copy link**."},{"id":"hosting","title":"Hosting a project","summary":"Host builds your project, starts it on this computer, checks it, and only then shows a public HTTPS link.","related":["safety","sessions","getting-started"],"body":"Host builds your project, starts it on this computer, checks it, and only then shows a public HTTPS link.\n\n## The steps you see\n\n| Step | What happens |\n| --- | --- |\n| Inspect project | Reads the Dockerfile or Compose file and finds the web port and service. |\n| Prepare tunnel helper | Uses an installed `cloudflared`, or downloads and verifies the pinned release. |\n| Build app | Runs `docker build`, or `docker compose up --build` for Compose. |\n| Start container | Starts an app-owned container bound to `127.0.0.1` on a free port. |\n| Check local health | Requests the app over HTTP until it answers. |\n| Open and verify public link | Creates a Quick Tunnel and requests the public HTTPS address. |\n\nEach step shows its own spinner and timing. If a step fails, the message and the recovery buttons appear on that step, so you never hunt for what went wrong.\n\n## Truthful states\n\nThe link card appears only when the backend reports a verified public address. A link printed in the tunnel's log is not enough. If the app stops answering, the link is cleared at once and the screen says so.\n\n## Stopping\n\n**Stop sharing…** opens a two-key confirmation, because visitors lose access immediately. Stopping removes the app-owned container, image and tunnel. Docker volumes and every container the app did not create are left alone. Closing the app also stops sharing.\n\n## Limits of Quick Tunnels\n\n- Up to 200 requests in flight at once.\n- Server-sent events are not supported.\n- There is no uptime guarantee, and each session gets a new address.\n\nRead the provider's notes at https://developers.cloudflare.com/tunnel/get-started/quick-tunnels/."},{"id":"languages","title":"Languages and voice","summary":"The app and the website speak English, Hong Kong Cantonese, or both side by side.","related":["narrator","vocabulary","school-mode"],"body":"The app and the website speak English, Hong Kong Cantonese, or both side by side.\n\n## Language modes\n\n- **English**.\n- **廣東話**: written Hong Kong Cantonese in traditional characters.\n- **Bilingual**: the English label stays first, with the Cantonese label smaller beside or under it. Narrow windows wrap the second label instead of squeezing it.\n\nChange it in **Settings › Language and voice**, or in the first-run tour. The choice is saved on this computer; the website saves its own choice in your browser.\n\n## Playfulness\n\nTwo sliders, one for English and one for Cantonese, go from **1 (serious)** to **5 (playful)**. They change the voice of headings, notifications and empty states. Facts never change: an error still names the same cause and the same fix at every level. Both ship at 5 and reset separately.\n\n## Emoji in dialogs\n\nWhen turned on, confirmations and notifications get one small emoji. Emoji never appear in buttons, labels or the names read by screen readers."},{"id":"motion-and-sound","title":"Motion and sound","summary":"Movement explains what changed. Sound confirms what happened. Both can be turned down or off.","related":["appearance","focus-modes","accessibility"],"body":"Movement explains what changed. Sound confirms what happened. Both can be turned down or off.\n\n## Motion levels\n\n- **Full**: cards rise in, the link card grows into place, the tunnel line flows while sharing, and a failure gives one short shake.\n- **Gentle**: shorter, smaller movements and no looping animation.\n- **Off**: instant changes. This is also used whenever your system asks for reduced motion, whatever you choose here.\n\nMotion never carries meaning on its own. Every state also changes its text, colour or icon.\n\n## Action sounds\n\nShort tones play when hosting starts, when the link goes live, when sharing stops and when hosting fails. They are made by the app itself, so no audio files are loaded. Turn them off or set the volume in **Settings › Motion and sound**. The setting applies at once and is remembered."},{"id":"narrator","title":"Narrator","summary":"The narrator reads progress, results and notifications aloud with the voices installed on this computer. It is off until you turn it on in Settings › Language and voice.","related":["languages","accessibility","notifications"],"body":"The narrator reads progress, results and notifications aloud with the voices installed on this computer. It is off until you turn it on in **Settings › Language and voice**.\n\n## Voices\n\n- **English voice** and **Cantonese voice** each list only the matching voices installed on this computer. **Choose automatically** picks the first English voice, and the first Hong Kong Cantonese voice.\n- Under each picker, **In use** names the voice that will really speak. If no Cantonese voice is installed, it says so; install one from your operating system's speech settings.\n- **Narrator speed** and **Narrator pitch** go from 0.5 to 2.\n\nIn bilingual mode, the English line is spoken first with the English voice and the Cantonese line next with the Cantonese voice. The same message is never repeated within four seconds.\n\n## Not built yet\n\nThe narrator does not detect a running screen reader yet, so turn one of them off if you hear both."},{"id":"notifications","title":"Notifications","summary":"Small messages appear in the corner and never block what you are doing.","related":["getting-around","settings","sessions"],"body":"Small messages appear in the corner and never block what you are doing.\n\n## Toasts\n\nSuccess and information messages appear at the bottom and fade after the time you choose in **Settings › Notifications** (3 to 15 seconds). Errors and warnings stay until you dismiss them. Several toasts stack without covering each other.\n\n## The notification centre\n\nPress the bell in the top bar. Every notification is kept there, newest first, with its time. Search it (with the regex builder), select several to dismiss them, export them as JSON, or **Clear all…** with the two-key confirmation. The bell's badge counts unread notifications."},{"id":"safety","title":"Two-key confirmation","summary":"Actions that cannot be undone ask for two separate keys and a slide before they run.","related":["hosting","sessions","settings"],"body":"Actions that cannot be undone ask for two separate keys and a slide before they run.\n\n## Which actions use it\n\n- **Stop sharing** while a link is live.\n- **Clear session history** and **Remove** selected sessions.\n- **Reset all settings** and **Clear all** notifications.\n\n## How it works\n\n1. The confirmation names the exact action and what it affects.\n2. Turn **Key 1** and **Key 2**. Each is its own button, so one stray press is never enough.\n3. The slider unlocks. Drag it all the way to the end, or use the arrow keys, to confirm.\n4. **Emergency exit** or **Escape** closes it at any time, and focus returns to the button you started from.\n\nNothing happens until both keys are on and the slider reaches the end. With motion turned off, the key and slider states still change colour and text, so the confirmation stays clear."},{"id":"schedules","title":"Schedules","summary":"Change settings automatically at set times.","related":["settings","appearance","focus-modes"],"body":"Change settings automatically at set times.\n\n**Settings › Schedules** lists your schedules. Each one has a name, a start and end time, the values it sets (theme, motion, action sounds and focus) and a switch. Two examples ship turned off: **Evening** (dark theme and gentle motion from 18:00 to 07:00) and **Work hours** (focus from 09:00 to 17:00).\n\n## How they apply\n\n- Times use this computer's local time, so daylight-saving changes follow your system clock.\n- A schedule applies once, when its time window starts. If you change a setting by hand afterwards, your change stays until the next schedule starts.\n- When windows overlap, the schedule higher in the list wins.\n- A window that ends earlier than it starts, such as 18:00 to 07:00, runs overnight.\n- Each scheduled change is recorded in settings history with the schedule's name.\n\n## Not built yet\n\nDate ranges, weekday-only rules and outside sources such as a web service or home automation are planned."},{"id":"school-mode","title":"School mode","summary":"A simple, focused version of the app for classrooms.","related":["languages","settings","vocabulary"],"body":"A simple, focused version of the app for classrooms.\n\nWhile School mode is on, the app uses English only, plain wording, no emoji, no personal vocabulary and no dim sum surprise. Those settings are left out of Settings and the command palette instead of being shown disabled.\n\n## Turning it on and off\n\nTurn it on in **Settings › Language and voice** and choose a PIN of 4 to 12 digits. Turning it off asks for that PIN. The PIN is stored on this computer as a salted SHA-256 hash.\n\nSchool mode is a convenience lock, not a security boundary: clearing the app's data on this computer resets it.\n\n## Not built yet\n\nSharing one School mode switch across several apps on the same computer is planned."},{"id":"search-and-regex","title":"Search and the regex builder","summary":"Every search box in the app and on the website has a regex builder right beside it.","related":["command-palette","sessions","settings"],"body":"Every search box in the app and on the website has a regex builder right beside it.\n\n## Plain search\n\nType to filter. Plain search ignores case and matches any part of the text.\n\n## Regex search\n\nPress **.\\*** beside a search box. The builder opens under it with:\n\n- **Live explanation**: each part of the pattern is listed with what it means, for example `^` as start of text or `(a|b)` as a group with two choices.\n- **Flags**: `i` ignore case, `m` multiline, `s` dot matches newline, `u` Unicode.\n- **Match count** for the current screen.\n- **Validation**: an invalid pattern says why and matches nothing.\n\nEach search keeps its own pattern and flags, so the Sessions search never changes the Settings search.\n\n## Safety limits\n\nPatterns are limited to 300 characters and each searched text to 20,000 characters. Patterns that repeat a repeated group, such as `(a+)+`, are blocked because they can freeze a search.\n\n## What is not built yet\n\nThe builder is not a full RegexBuddy equivalent. Debugging, a library of saved patterns and engine comparisons are planned."},{"id":"sessions","title":"Sessions and history","summary":"Every hosting attempt is saved on this computer so you can look back, search and export.","related":["safety","search-and-regex","settings"],"body":"Every hosting attempt is saved on this computer so you can look back, search and export.\n\n## What a session records\n\nThe file you hosted, the format, the service and port, every step with its time, the outcome (shared, failed, cancelled) and the public address it had. Nothing is uploaded.\n\n## Search and filters\n\n- The search box matches names, paths, addresses and outcomes. Turn on the **.\\*** regex builder for patterns.\n- The outcome chips filter the list, and **Statistics** folds open to show totals, time shared and how many attempts reached live, with a chart of the last 14 days by outcome. Hover a bar for its day and count; screen readers get the same numbers as a table.\n- The filters and the statistics panel remember whether they were open.\n\n## Bulk actions\n\nTick sessions (or **Select all**) to **Export selected** or **Remove…**. Removing uses the two-key confirmation.\n\n## Export formats\n\n- **JSON**: every field, re-importable, UTF-8 with schema version 1.\n- **CSV**: one row per session, UTF-8, CRLF line endings for spreadsheets. Step timings are left out; the file says so in its header row.\n- **Markdown**: a readable table.\n\n## Settings history\n\nEvery settings change is saved as a revision in **Settings › Data and history**. **Restore** brings back an older revision as a new one, so history is never rewritten."},{"id":"settings","title":"Settings","summary":"Everything is saved on this computer, explained in place, searchable, and resettable group by group.","related":["languages","appearance","safety"],"body":"Everything is saved on this computer, explained in place, searchable, and resettable group by group.\n\n## Groups\n\n- **Appearance**: theme and accent colour.\n- **Motion and sound**: motion level, action sounds and volume.\n- **Language and voice**: language mode, playfulness sliders and dialog emoji.\n- **Focus modes**: five separate switches.\n- **Accessibility**: text size, density and command palette size.\n- **Notifications**: how long notifications stay.\n- **Data and history**: settings history with restore, exports, and resets.\n- **About**: version and build time, changelog, the app's name and the welcome tour.\n\nEach setting has an **info** button that explains what it changes. The search at the top finds settings by name or description, with the regex builder beside it.\n\n## Renaming the app\n\n**About › App name** changes the name shown in the window title and the header. **Restore original name** puts it back. Data folders, the package and the update source keep the original name.\n\n## Resetting\n\n**Reset this group** resets one group. **Reset all settings…** resets everything after a two-key confirmation. Old values stay in settings history."},{"id":"tabs","title":"Tabs","summary":"Keep a few screens one click away.","related":["getting-around","command-palette"],"body":"Keep a few screens one click away.\n\nOrdinary navigation never opens tabs. The **Workspace** tab follows the rail as usual. You open extra tabs yourself:\n\n- Press **Ctrl+T**, or select **+** in the tab strip, to open the New tab catalogue.\n- The catalogue lists screens, tools, settings groups and guide articles. Type to filter it.\n- Choose an entry to open it in a new tab.\n\n## Keys\n\n- **Ctrl+Tab** and **Ctrl+Shift+Tab** move between tabs.\n- **Ctrl+W** closes the current tab. The Workspace tab cannot be closed.\n- With a tab focused, the **arrow keys**, **Home** and **End** move between tabs, and **Delete** closes it.\n- **Enter** or **Space** opens a focused tab.\n\nOpen tabs are remembered between sessions. The strip is hidden while only the Workspace tab is open."},{"id":"tools","title":"Tools: Base64 and Convert","summary":"Two local helpers on the Tools screen. Nothing you paste or open there leaves this computer.","related":["getting-around","sessions","accessibility"],"body":"Two local helpers on the **Tools** screen. Nothing you paste or open there leaves this computer.\n\n## Base64\n\n- **Encode** text or a file, or **Decode** Base64 back to text.\n- **Alphabet**: standard, URL-safe (`-` and `_`) or MIME, which wraps lines at 76 characters.\n- **Padding** can be turned off for encoders that expect no `=` at the end.\n- **Text encoding**: UTF-8, UTF-16 LE or Latin-1, for both directions.\n- **Strict decoding** rejects anything outside the alphabet and names the exact position of the first problem. Turn it off to skip spaces and line breaks and accept either alphabet.\n- **As data: URL** wraps the output as `data:<type>;base64,...`. Pasting a `data:` URL into Decode reads it back.\n\nEvery encode is checked by decoding it again and comparing SHA-256 hashes; the result says **SHA-256 round trip verified**. Decoded data that is not valid text is shown as hexadecimal and cannot be saved as text.\n\n**Recent conversions** keeps this session's inputs, so **Restore input** brings any of them back.\n\n## Convert\n\nTurn a JSON list of objects, CSV or TSV into CSV, TSV, Markdown or JSON. Before you copy or save, the screen says what the conversion cannot carry, for example that numbers become plain text or that nested objects are written as JSON text in one cell.\n\n## Not built yet\n\nStreaming very large files with pause and cancel, MIME type detection with a preview, ZIP export and YAML are planned."},{"id":"updates","title":"Installing and updates","summary":"Download Tunnel-App-Deployer-Setup-x.y.z.exe from the latest release and run it. It installs for your Windows account only, with no administrator prompt, and adds Start menu and desktop shortcuts. Uninstall it from Settings › Apps in Windows.","related":["about","settings","safety"],"body":"## Install\n\nDownload **Tunnel-App-Deployer-Setup-x.y.z.exe** from the latest release and run it. It installs for your Windows account only, with no administrator prompt, and adds Start menu and desktop shortcuts. Uninstall it from **Settings › Apps** in Windows.\n\nThe installer is unsigned. Windows may show an unknown-publisher or SmartScreen warning.\n\n## Automatic updates\n\nAn installed copy checks the release feed in the background shortly after it starts and then every four hours. When a newer version is found it downloads quietly. When it is ready, a banner offers **Restart to update** or **Later**. Nothing restarts without your choice, and a running tunnel is stopped cleanly first.\n\nThe banner says the update is unsigned. The download is checked against the hash in the release feed, which proves it is intact. It does not prove who published it.\n\n**Settings › About** shows the update state and has **Check for updates**. Copies that were not installed with the installer, such as a development build, say that updates are unavailable.\n\n## Code names\n\nEvery release is named after a dim sum dish from the public dim sum photo catalogue, shown in **Settings › About** with its photo. A dish is never reused."},{"id":"vocabulary","title":"Personal vocabulary","summary":"Replace words in the interface with your own, from a small JSON file.","related":["languages","settings","school-mode"],"body":"Replace words in the interface with your own, from a small JSON file.\n\n## The file\n\n```\n{\"version\": 1, \"entries\": {\"Host\": \"Share\", \"Sessions\": \"History\"}}\n```\n\nEach entry replaces a whole word or phrase in interface text, never inside your data, paths or links. The file is checked in full before anything changes: at most 256 KiB, nested at most 8 levels deep, words up to 160 characters and replacements up to 1,000. A file that fails any check is rejected with the reason, and nothing from it is applied.\n\n## Loading it\n\nPress **Upload JSON** in **Settings › Language and voice**, or drop the file anywhere on the app window. **Use personal vocabulary** turns the replacements off without removing them, and **Clear vocabulary** deletes the stored copy.\n\n## Privacy\n\nThe vocabulary is stored on this computer only, in its own record. It is never included in settings exports, settings history, notifications or session exports."}],"changelog":{"schema":1,"repository":"https://github.com/Ding-Ding-Projects/tunnel-app-deployer","entries":[{"version":"0.2","date":"2026-11-06","commit":null,"note":"Released automatically from main; each release's exact version and commit are shown in its build record.","changes":{"Added":["Material Design 3 redesign with a navigation rail, a bottom bar for narrow windows and a live tunnel diagram","Sessions history with search, filters, statistics, bulk actions and JSON, CSV or Markdown export","Features screen with an honest status for every planned feature","Offline guide with every website article","Settings with search, regex builder, settings history and per-group reset","English, Hong Kong Cantonese and bilingual modes with playfulness sliders","Command palette on Ctrl+Shift+F, context menus, notification centre and two-key confirmations","Focus modes, text size, density, accent colour, motion levels and action sounds","Version and build time on the first screen, and a release on every build of main"],"Changed":["The navigation rail writes each destination's name beside its icon on wide windows; the menu button at its top, or Settings › Appearance › Navigation rail, collapses it to the compact rail","The website was rebuilt with the feature inventory, articles, language modes and a command palette","Windows title bar drawn by the app, with the version, dim sum code name and build time, and Windows' own caption buttons and Snap layouts","One Material 3 type scale, focus rings around search boxes, menu items and date fields, and buttons whose corners square up when pressed","Settings rows stack their controls under the label on narrow windows; schedule rules reflow to fit","The public link wraps only after dots, dashes and slashes, and steps down in size on narrow windows","No toast for news the Host screen already shows; the bell still records it"],"Fixed":["Text size above 100 percent cut off the bottom of the window","Screen readers read icon names such as \"content_copy\"; menus, tabs and the bottom navigation used invalid roles","Cantonese text inside filled buttons had too little contrast; Starting status was below 4.5 to 1 in the light theme","Schedule switches showed untranslated on and off, and the confirm slider covered its own instruction","Sessions chart date labels shrank to unreadable sizes on narrow windows","Website dialogs let the keyboard leave them; the Show all features button had a grey browser fill"]}},{"version":"0.1.0","date":"2026-11-06","commit":"0d71e2b2c3636e2156cbf87006b7a3d2ba3232fe","note":"Development preview. Not published as a release.","changes":{"Added":["Host a Dockerfile or Compose project and share it through a verified Cloudflare Quick Tunnel","Pinned, hash-verified tunnel helper download","Isolated, app-owned containers with cleanup that keeps volumes","Windows portable build in CI"]}}]}};
  if (typeof module === 'object' && module.exports) module.exports = data; else root.Content = data; })(typeof window === 'undefined' ? globalThis : window);
